#!/bin/sh
# Generate the abbreviation tables for VS Code, Emacs and the server from
# editors/abbreviations.tsv (one `name<TAB>symbol` per line).
#
#   editors/gen-abbreviations.sh           rewrite the generated files
#   editors/gen-abbreviations.sh --check   fail if they are out of date
set -eu

root=$(cd "$(dirname "$0")/.." && pwd)
tsv="$root/editors/abbreviations.tsv"

ts=editors/vscode/src/abbreviations.ts
el=editors/emacs/local/caraml-mode/caraml-input.el
hs=haskell/src/CaraML/Lsp/Abbreviations.hs

case "${1-}" in
  '')      out=$root ;;
  --check) out=$(mktemp -d); trap 'rm -rf "$out"' EXIT ;;
  *)       echo "usage: $0 [--check]" >&2; exit 2 ;;
esac

mkdir -p "$out/$(dirname "$ts")" "$out/$(dirname "$el")" "$out/$(dirname "$hs")"

LC_ALL=C awk -F '\t' -v ts="$out/$ts" -v el="$out/$el" -v hs="$out/$hs" '
  function esc(s, q) { gsub(/\\/, "\\\\", s); gsub(q, "\\" q, s); return s }
  # an Emacs ?-literal needs a backslash before these ASCII characters
  function elchar(c) { return (length(c) == 1 && index("()[]\";\\\x27`?#,.|", c) ? "\\" c : c) }

  NF == 0 { next }
  NF != 2 { printf "%s:%d: expected name<TAB>symbol\n", FILENAME, NR > "/dev/stderr"; bad = 1; exit 1 }
  { name[++n] = $1; sym[n] = $2 }

  END {
    if (bad) exit 1
    gen = "Generated by editors/gen-abbreviations.sh, do not edit."

    print "// " gen > ts
    print "" > ts
    print "export const abbreviations: ReadonlyMap<string, string> = new Map([" > ts
    for (i = 1; i <= n; i++)
      printf "  [\x27%s\x27, \x27%s\x27],\n", esc(name[i], "\x27"), esc(sym[i], "\x27") > ts
    print "]);" > ts

    print ";;; caraml-input.el --- input method for CaraML symbols -*- lexical-binding: t; -*-" > el
    print ";;; Commentary:" > el
    print ";; " gen > el
    print ";;; Code:" > el
    print "" > el
    print "(require \x27quail)" > el
    print "" > el
    print "(quail-define-package" > el
    print " \"caraml\" \"UTF-8\" \"∘\" t" > el
    print " \"CaraML symbols by backslash abbreviation: \\\\alpha, \\\\to, \\\\le, \\\\circ.\"" > el
    print " nil t nil nil nil nil t)" > el
    print "" > el
    print "(quail-define-rules" > el
    for (i = 1; i <= n; i++)
      printf " (\"\\\\%s\" ?%s)%s\n", esc(name[i], "\""), elchar(sym[i]), (i == n ? ")" : "") > el
    print "" > el
    print "(provide \x27caraml-input)" > el
    print ";;; caraml-input.el ends here" > el

    print "{-# LANGUAGE OverloadedStrings #-}" > hs
    print "-- " gen > hs
    print "module CaraML.Lsp.Abbreviations (abbreviations) where" > hs
    print "" > hs
    print "import Data.Text (Text)" > hs
    print "" > hs
    print "abbreviations :: [(Text, Text)]" > hs
    print "abbreviations =" > hs
    for (i = 1; i <= n; i++)
      printf "  %s (\"%s\", \"%s\")\n", (i == 1 ? "[" : ","), esc(name[i], "\""), esc(sym[i], "\"") > hs
    print "  ]" > hs
  }
' "$tsv"

if [ "$out" != "$root" ]; then
  stale=0
  for f in "$ts" "$el" "$hs"; do
    if ! cmp -s "$out/$f" "$root/$f"; then
      echo "out of date: $f (run editors/gen-abbreviations.sh)" >&2
      stale=1
    fi
  done
  exit "$stale"
fi
